window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9f4bbf4997e1eede"]={"versions": [{"id": "FIG-9f4bbf4997e1eede", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Abhängigkeiten zwischen Datentypen, Datenelementen und Record-Layouts innerhalb des AUTOSAR-Software-Component-Templates. Dargestellt ist das Zusammenspiel von Prototypen, Datentypdefinitionen und softwaretechnischen Eigenschaften (Software Data Definition Properties).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«atpPrototype» DataElementPrototype</code>: Repräsentiert das konkrete Datenelement, typisiert über die gerichtete Assoziation <code>«isOfType»</code> auf <code>«atpType» DataType</code>. Enthält als Komposition die Entität <code>SwDataDefProps</code>.\n</li><li><code>«atpType» DataType</code>: Typdefinition für das Datenelement.\n</li><li><code>SwDataDefProps</code>: Bündelt softwaretechnische Definitionseigenschaften; referenziert über gerichtete Assoziationen <code>SwRecordLayout</code>, <code>BaseType</code> sowie <code>SwCodeSyntax</code>.\n</li><li><code>SwRecordLayout</code>: Definiert das Speicher- und Übertragungslayout für zusammengesetzte Datenstrukturen; besitzt eine Abhängigkeitsbeziehung (gestrichelter Pfeil mit offener Spitze) zu <code>DataType</code> sowie eine Abhängigkeit zu <code>BaseType</code>.\n</li><li><code>BaseType</code>: Repräsentiert den zugrundeliegenden primitiven Basistyp.\n</li><li><code>SwCodeSyntax</code>: Spezifiziert codespezifische Syntaxvorgaben mit einer Abhängigkeitsbeziehung zu <code>DataType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Strukturierung von AUTOSAR-M1-Beschreibungen im SWC-Template. Modelliert die Zuordnung von Layouts und Syntaxdefinitionen zu Datenelementen und deren Typen. Konformitätsprüfungen müssen sicherstellen, dass bei der Definition von Datenelement-Prototypen die zugehörigen <code>SwDataDefProps</code> konsistent auf Basistypen, Record-Layouts und Code-Syntaxen verweisen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0fceae069d8bd2f4", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Abhängigkeiten zwischen Datentypen, Datenelementen und Record-Layouts innerhalb des AUTOSAR-Software-Component-Templates. Dargestellt ist das Zusammenspiel von Prototypen, Datentypdefinitionen und softwaretechnischen Eigenschaften (Software Data Definition Properties).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«atpPrototype» DataElementPrototype</code>: Repräsentiert das konkrete Datenelement, typisiert über die gerichtete Assoziation <code>«isOfType»</code> auf <code>«atpType» DataType</code>. Enthält als Komposition die Entität <code>SwDataDefProps</code>.\n</li><li><code>«atpType» DataType</code>: Typdefinition für das Datenelement.\n</li><li><code>SwDataDefProps</code>: Bündelt softwaretechnische Definitionseigenschaften; referenziert über gerichtete Assoziationen <code>SwRecordLayout</code>, <code>BaseType</code> sowie <code>SwCodeSyntax</code>.\n</li><li><code>SwRecordLayout</code>: Definiert das Speicher- und Übertragungslayout für zusammengesetzte Datenstrukturen; besitzt eine Abhängigkeitsbeziehung (gestrichelter Pfeil mit offener Spitze) zu <code>DataType</code> sowie eine Abhängigkeit zu <code>BaseType</code>.\n</li><li><code>BaseType</code>: Repräsentiert den zugrundeliegenden primitiven Basistyp.\n</li><li><code>SwCodeSyntax</code>: Spezifiziert codespezifische Syntaxvorgaben mit einer Abhängigkeitsbeziehung zu <code>DataType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Strukturierung von AUTOSAR-M1-Beschreibungen im SWC-Template. Modelliert die Zuordnung von Layouts und Syntaxdefinitionen zu Datenelementen und deren Typen. Konformitätsprüfungen müssen sicherstellen, dass bei der Definition von Datenelement-Prototypen die zugehörigen <code>SwDataDefProps</code> konsistent auf Basistypen, Record-Layouts und Code-Syntaxen verweisen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ec16507ac7095e02", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Darstellung der Abhängigkeiten und des Mappings zwischen Datentypen und Record-Layouts im AUTOSAR-Software-Component-Template. Es verdeutlicht die Entkopplung von Anwendungs- und Implementierungsdatentypen sowie deren Beziehung zu Speicherlayouts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>element : DataTypeMap</code>: Instanzelement, das das Mapping zwischen Anwendungs- und Implementierungsebene definiert; besitzt gerichtete Assoziationen zu <code>:ApplicationDataType</code> und <code>:ImplementationDatatype</code>.\n</li><li><code>:ApplicationDataType</code>: Repräsentiert die anwendungsseitige Datentypinstanz; enthält per Komposition <code>:SwDataDefProps</code>.\n</li><li><code>:SwDataDefProps</code>: Instanz der Software Data Definition Properties; verweist per gerichteter Assoziation auf <code>:SwRecordLayout</code>.\n</li><li><code>:ImplementationDatatype</code>: Repräsentiert die maschinen- bzw. plattformnahe Datentypimplementierung; referenziert per gerichteter Assoziation <code>:BaseType</code>.\n</li><li><code>:SwRecordLayout</code>: Spezifiziert das konkrete Record-Layout; referenziert per gerichteter Assoziation <code>:BaseType</code> und weist eine gestrichelte Abhängigkeitsbeziehung zu <code>:ImplementationDatatype</code> auf.\n</li><li><code>:BaseType</code>: Instanz des primitiven Basistyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Interaktions- oder Ablaufmodellierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die Modellierung von Datentyp-Transformationen mittels <code>DataTypeMap</code>. Entwickler und Generatoren müssen berücksichtigen, dass <code>SwDataDefProps</code> an <code>ApplicationDataType</code> gebunden ist und über <code>SwRecordLayout</code> auf den plattformspezifischen <code>ImplementationDatatype</code> sowie den <code>BaseType</code> abgebildet wird.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6fc345e5a7fbe1d6", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Abhängigkeiten zwischen Datentypen, Datenelementen und Record-Layouts innerhalb des AUTOSAR-Software-Component-Templates. Dargestellt ist das Zusammenspiel von Prototypen, Datentypdefinitionen und softwaretechnischen Eigenschaften (Software Data Definition Properties).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«atpPrototype» DataElementPrototype</code>: Repräsentiert das konkrete Datenelement, typisiert über die gerichtete Assoziation <code>«isOfType»</code> auf <code>«atpType» DataType</code>. Enthält als Komposition die Entität <code>SwDataDefProps</code>.\n</li><li><code>«atpType» DataType</code>: Typdefinition für das Datenelement.\n</li><li><code>SwDataDefProps</code>: Bündelt softwaretechnische Definitionseigenschaften; referenziert über gerichtete Assoziationen <code>SwRecordLayout</code>, <code>BaseType</code> sowie <code>SwCodeSyntax</code>.\n</li><li><code>SwRecordLayout</code>: Definiert das Speicher- und Übertragungslayout für zusammengesetzte Datenstrukturen; besitzt eine Abhängigkeitsbeziehung (gestrichelter Pfeil mit offener Spitze) zu <code>DataType</code> sowie eine Abhängigkeit zu <code>BaseType</code>.\n</li><li><code>BaseType</code>: Repräsentiert den zugrundeliegenden primitiven Basistyp.\n</li><li><code>SwCodeSyntax</code>: Spezifiziert codespezifische Syntaxvorgaben mit einer Abhängigkeitsbeziehung zu <code>DataType</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Strukturierung von AUTOSAR-M1-Beschreibungen im SWC-Template. Modelliert die Zuordnung von Layouts und Syntaxdefinitionen zu Datenelementen und deren Typen. Konformitätsprüfungen müssen sicherstellen, dass bei der Definition von Datenelement-Prototypen die zugehörigen <code>SwDataDefProps</code> konsistent auf Basistypen, Record-Layouts und Code-Syntaxen verweisen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9899665f90ff366f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Darstellung der Abhängigkeiten und des Mappings zwischen Datentypen und Record-Layouts im AUTOSAR-Software-Component-Template. Es verdelicht die Entkopplung von Anwendungs- und Implementierungsdatentypen sowie deren Beziehung zu Speicherlayouts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>element : DataTypeMap</code>: Instanzelement, das das Mapping zwischen Anwendungs- und Implementierungsebene definiert; besitzt gerichtete Assoziationen zu <code>:ApplicationDataType</code> und <code>:ImplementationDatatype</code>.\n</li><li><code>:ApplicationDataType</code>: Repräsentiert die anwendungsseitige Datentypinstanz; enthält per Komposition <code>:SwDataDefProps</code>.\n</li><li><code>:SwDataDefProps</code>: Instanz der Software Data Definition Properties; verweist per gerichteter Assoziation auf <code>:SwRecordLayout</code>.\n</li><li><code>:ImplementationDatatype</code>: Repräsentiert die maschinen- bzw. plattformnahe Datentypimplementierung; referenziert per gerichteter Assoziation <code>:BaseType</code>.\n</li><li><code>:SwRecordLayout</code>: Spezifiziert das konkrete Record-Layout; referenziert per gerichteter Assoziation <code>:BaseType</code> und weist eine gestrichelte Abhängigkeitsbeziehung zu <code>:ImplementationDatatype</code> auf.\n</li><li><code>:BaseType</code>: Instanz des primitiven Basistyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Interaktions- oder Ablaufmodellierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die Modellierung von Datentyp-Transformationen mittels <code>DataTypeMap</code>. Entwickler und Generatoren müssen berücksichtigen, dass <code>SwDataDefProps</code> an <code>ApplicationDataType</code> gebunden ist und über <code>SwRecordLayout</code> auf den plattformspezifischen <code>ImplementationDatatype</code> sowie den <code>BaseType</code> abgebildet wird.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9f4bbf4997e1eede", "to": "FIG-0fceae069d8bd2f4", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0fceae069d8bd2f4", "to": "FIG-ec16507ac7095e02", "fr": "R3.0.7", "tr": "R3.1.5", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metamodellierung grundlegend überarbeitet: Wechsel von Klassenebene (<code>DataType</code>, <code>DataElementPrototype</code>, <code>BaseType</code>, <code>SwCodeSyntax</code>) zu Instanzebene/Objektdiagramm (<code>:ApplicationDataType</code>, <code>:ImplementationDatatype</code>, <code>:BaseType</code>, <code>element : DataTypeMap</code>).\n</li><li>Element <code>«atpPrototype» DataElementPrototype</code> sowie Assoziation <code>«isOfType»</code> entfallen; stattdessen ist <code>:SwDataDefProps</code> per Komposition direkt <code>:ApplicationDataType</code> zugeordnet.\n</li><li>Element <code>SwCodeSyntax</code> entfällt.\n</li><li>Element <code>element : DataTypeMap</code> eingefügt mit gerichteten Assoziationen auf <code>:ApplicationDataType</code> und <code>:ImplementationDatatype</code>.\n</li><li>Direkte gerichtete Assoziation von <code>:ImplementationDatatype</code> auf <code>:BaseType</code> ergänzt.\n</li><li>Abhängigkeitsbeziehung von <code>:SwRecordLayout</code> zeigt nun auf <code>:ImplementationDatatype</code> statt auf <code>DataType</code>.\n</li><li>Referenz von <code>SwDataDefProps</code> auf <code>BaseType</code> entfällt.\n</li><li>Referenz von <code>SwRecordLayout</code> auf <code>BaseType</code> wird nun als orthogonale gerichtete Assoziation modelliert.\n</li></ul>"}, {"from": "FIG-ec16507ac7095e02", "to": "FIG-6fc345e5a7fbe1d6", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metamodellierung zurückgesetzt auf Klassenebene: Instanzen (<code>:ApplicationDataType</code>, <code>:ImplementationDatatype</code>, <code>:BaseType</code>, <code>element : DataTypeMap</code>) entfallen.\n</li><li>Elemente <code>«atpPrototype» DataElementPrototype</code> mit Assoziation <code>«isOfType»</code> auf <code>«atpType» DataType</code> wieder eingefügt.\n</li><li>Element <code>SwDataDefProps</code> ist wieder per Komposition <code>DataElementPrototype</code> untergeordnet.\n</li><li>Element <code>SwCodeSyntax</code> wieder eingefügt mit gerichteter Assoziation von <code>SwDataDefProps</code> und Abhängigkeit (gestrichelter Pfeil) zu <code>DataType</code>.\n</li><li>Abhängigkeitsbeziehung von <code>SwRecordLayout</code> zielt wieder auf <code>DataType</code>.\n</li><li>Direkte gerichtete Referenz von <code>SwDataDefProps</code> auf <code>BaseType</code> wieder eingefügt.\n</li><li>Direkte Referenz von <code>SwRecordLayout</code> auf <code>BaseType</code> wieder als Abhängigkeit (gestrichelter Pfeil) modelliert.\n</li><li>Assoziation von Datentyp auf <code>BaseType</code> entfällt.\n</li></ul>"}, {"from": "FIG-6fc345e5a7fbe1d6", "to": "FIG-9899665f90ff366f", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metamodellierung erneut überarbeitet: Wechsel von Klassenebene (<code>DataType</code>, <code>DataElementPrototype</code>, <code>BaseType</code>, <code>SwCodeSyntax</code>) zu Instanzebene (<code>:ApplicationDataType</code>, <code>:ImplementationDatatype</code>, <code>:BaseType</code>, <code>element : DataTypeMap</code>).\n</li><li>Element <code>«atpPrototype» DataElementPrototype</code> sowie Assoziation <code>«isOfType»</code> entfallen; <code>:SwDataDefProps</code> ist per Komposition direkt <code>:ApplicationDataType</code> zugeordnet.\n</li><li>Element <code>SwCodeSyntax</code> entfällt.\n</li><li>Element <code>element : DataTypeMap</code> ergänzt mit Assoziationen auf <code>:ApplicationDataType</code> und <code>:ImplementationDatatype</code>.\n</li><li>Direkte gerichtete Assoziation von <code>:ImplementationDatatype</code> auf <code>:BaseType</code> ergänzt.\n</li><li>Abhängigkeitsbeziehung von <code>:SwRecordLayout</code> zeigt auf <code>:ImplementationDatatype</code> statt auf <code>DataType</code>.\n</li><li>Referenz von <code>SwDataDefProps</code> auf <code>BaseType</code> entfällt.\n</li><li>Referenz von <code>:SwRecordLayout</code> auf <code>:BaseType</code> als gerichtete Assoziation ausgeführt.\n</li></ul>"}]};
